def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def factorial_checked(n):
    if type(n) is not int:
        raise TypeError("n 必须是整数")
    if n < 0:
        raise ValueError("n 必须是非负数")
    if n <= 1:
        return 1
    return n * factorial_checked(n - 1)

def factorial_loop(n):
    result = 1
    for k in range(2, n + 1):
        result = result * k
    return result

